require_once __DIR__.'/../includes/admin-functions.php';$schema=dental_schema($pdo);$labId=$schema->labId();$serviceId=$schema->serviceId();$imageId=$schema->imageId();$imagePath=$schema->imagePath();$hasLabDate=$schema->hasCreatedAt();$hasImageDate=$schema->hasCreatedAt('image_laboratoire');$pending=$schema->status('en_attente');$valid=$schema->status('valide');$rejected=$schema->status('rejete');
$counts=['total'=>(int)$pdo->query('SELECT COUNT(*) FROM laboratoire')->fetchColumn()];foreach(['en_attente'=>$pending,'valide'=>$valid,'rejete'=>$rejected] as $key=>$status){$q=$pdo->prepare('SELECT COUNT(*) FROM laboratoire WHERE statut=?');$q->execute([$status]);$counts[$key]=(int)$q->fetchColumn();}$counts['services']=(int)$pdo->query('SELECT COUNT(*) FROM service')->fetchColumn();$counts['photos']=(int)$pdo->query('SELECT COUNT(*) FROM image_laboratoire')->fetchColumn();$counts['new_month']=$hasLabDate?(int)$pdo->query("SELECT COUNT(*) FROM laboratoire WHERE created_at>=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')")->fetchColumn():0;
$recentDate=$hasLabDate?'l.created_at':'NULL';$sortRecent=$hasLabDate?'l.created_at DESC,':' ';$imageSort=$hasImageDate?'i.created_at DESC,':'';$sql="SELECT l.`$labId` id,l.nom_laboratoire,l.nom_gerant,l.email,l.ville,l.statut,$recentDate created_at,(SELECT i.`$imagePath` FROM image_laboratoire i WHERE i.laboratoire_id=l.`$labId` ORDER BY $imageSort i.`$imageId` LIMIT 1) photo FROM laboratoire l ORDER BY $sortRecent l.`$labId` DESC LIMIT 8";$recent=$pdo->query($sql)->fetchAll();$rows=$hasLabDate?$pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') m,COUNT(*) n FROM laboratoire WHERE created_at>=DATE_SUB(CURRENT_DATE,INTERVAL 5 MONTH) GROUP BY m ORDER BY m")->fetchAll():[];$map=[];foreach($rows as $r)$map[$r['m']]=(int)$r['n'];$chart=[];for($i=5;$i>=0;$i--){$k=date('Y-m',strtotime("first day of -$i month"));$chart[]=['label'=>date('M',strtotime($k.'-01')),'n'=>$map[$k]??0];}$max=max(1,...array_column($chart,'n'));
$pageTitle='Administration — DentalLink';$assetPrefix='../';$navContext='admin';$pageStyles=['assets/css/admin.css'];$pageScripts=['assets/js/admin.js'];require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';$flash=admin_take_flash();
?>
<main class="admin-main"><div class="admin-heading"><div><p class="admin-eyebrow">Vue d’ensemble</p><h1>Administration</h1><p class="admin-muted">Activité réelle de DentalLink Morocco</p></div><a class="admin-button admin-primary" href="laboratoires.php?action=create">Ajouter un laboratoire</a></div><?php if($flash):?><div class="admin-alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?>
<section class="admin-stats"><?php foreach([['Total laboratoires',$counts['total'],'laboratoires.php',''],['En attente',$counts['en_attente'],'validation.php','warning'],['Validés',$counts['valide'],'laboratoires.php?statut=valide','success'],['Rejetés',$counts['rejete'],'laboratoires.php?statut=rejete','danger'],['Services',$counts['services'],'services.php',''],['Photos',$counts['photos'],'photos.php',''],['Nouvelles inscriptions ce mois',$counts['new_month'],'laboratoires.php?recent=1','']] as [$label,$number,$href,$class]):?><a class="stat-card stat-<?=e($class)?>" href="<?=e($href)?>"><span><?=e($label)?></span><strong><?=$number?></strong></a><?php endforeach;?></section>
<section class="admin-panels"><article class="admin-panel"><h2>Inscriptions par mois</h2><div class="chart-bars"><?php foreach($chart as $bar):?><div class="chart-column"><span><?=$bar['n']?></span><div style="height:<?=($bar['n']?max(5,(int)round($bar['n']/$max*100)):2)?>%"></div><small><?=e($bar['label'])?></small></div><?php endforeach;?></div></article><article class="admin-panel"><h2>Statuts</h2><?php foreach(['en_attente'=>'En attente','valide'=>'Validés','rejete'=>'Rejetés'] as $key=>$label):?><p class="status-row"><span><i class="status-dot dot-<?=$key?>"></i><?=e($label)?></span><strong><?=$counts[$key]?></strong></p><?php endforeach;?></article></section>
<section class="admin-panel"><div class="panel-heading"><h2>Dernières inscriptions</h2><a href="laboratoires.php">Tout afficher</a></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Laboratoire</th><th>Gérant</th><th>E-mail</th><th>Ville</th><th>Date</th><th>Statut</th><th></th></tr></thead><tbody><?php foreach($recent as $l):?><tr><td><div class="lab-cell"><?php if($l['photo']):?><img src="../<?=e($l['photo'])?>" alt=""><?php endif;?><strong><?=e($l['nom_laboratoire'])?></strong></div></td><td><?=e($l['nom_gerant'])?></td><td><?=e($l['email'])?></td><td><?=e($l['ville'])?></td><td><?=e(date('d/m/Y',strtotime($l['created_at'])))?></td><td><span class="status-badge status-<?=e($schema->canonicalStatus($l['statut']))?>"><?=e(admin_status_label($l['statut']))?></span></td><td><a href="laboratoires.php?id=<?=$l['id']?>">Détails</a></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="7" class="empty-cell">Aucune inscription.</td></tr><?php endif;?></tbody></table></div></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
